USE SPMS_DB;
-- Idempotent index creation so this script can be safely re-run.
SET @spms_index_ddl := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='employees' AND index_name='idx_employee_department_status')=0,'CREATE INDEX idx_employee_department_status ON employees(department_id,employment_status)','SELECT 1'); PREPARE spms_index_stmt FROM @spms_index_ddl; EXECUTE spms_index_stmt; DEALLOCATE PREPARE spms_index_stmt;
SET @spms_index_ddl := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='attendance' AND index_name='idx_attendance_date')=0,'CREATE INDEX idx_attendance_date ON attendance(work_date)','SELECT 1'); PREPARE spms_index_stmt FROM @spms_index_ddl; EXECUTE spms_index_stmt; DEALLOCATE PREPARE spms_index_stmt;
SET @spms_index_ddl := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='leave_requests' AND index_name='idx_leave_status_dates')=0,'CREATE INDEX idx_leave_status_dates ON leave_requests(status,start_date,end_date)','SELECT 1'); PREPARE spms_index_stmt FROM @spms_index_ddl; EXECUTE spms_index_stmt; DEALLOCATE PREPARE spms_index_stmt;
SET @spms_index_ddl := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='payroll' AND index_name='idx_payroll_month_status')=0,'CREATE INDEX idx_payroll_month_status ON payroll(pay_month,status)','SELECT 1'); PREPARE spms_index_stmt FROM @spms_index_ddl; EXECUTE spms_index_stmt; DEALLOCATE PREPARE spms_index_stmt;
SET @spms_index_ddl := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='performance' AND index_name='idx_performance_period')=0,'CREATE INDEX idx_performance_period ON performance(evaluation_period,evaluated_at)','SELECT 1'); PREPARE spms_index_stmt FROM @spms_index_ddl; EXECUTE spms_index_stmt; DEALLOCATE PREPARE spms_index_stmt;
SET @spms_index_ddl := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='reports' AND index_name='idx_reports_generated')=0,'CREATE INDEX idx_reports_generated ON reports(generated_at)','SELECT 1'); PREPARE spms_index_stmt FROM @spms_index_ddl; EXECUTE spms_index_stmt; DEALLOCATE PREPARE spms_index_stmt;
